commands:
[[ "$RUNTIME_URL" == https://* ]] || exit 1
[[ "$ARCHIVE_SHA" =~ ^[0-9a-fA-F]{64}$ ]] || exit 1
curl --fail --proto '=https' --tlsv1.2 "$RUNTIME_URL" -o /tmp/runtime.tar.gz
echo "$ARCHIVE_SHA  /tmp/runtime.tar.gz" | sha256sum -c -
mkdir /tmp/runtime
tar -xzf /tmp/runtime.tar.gz -C /tmp/runtime
python scripts/build-agent-package.py --os linux --runtime /tmp/runtime/otelcol-contrib --sha256 "$(sha256sum /tmp/runtime/otelcol-contrib | cut -d' ' -f1)" --output opscontrol-agent-linux.zip
bash -n agent/install-linux.sh agent/uninstall-linux.sh
if (-not $env:RUNTIME_URL.StartsWith('https://')) { throw 'HTTPS required' }
if ($env:ARCHIVE_SHA -notmatch '^[0-9a-fA-F]{64}$') { throw 'SHA-256 required' }
Invoke-WebRequest $env:RUNTIME_URL -OutFile "$env:TEMP\runtime.tar.gz"
if ((Get-FileHash "$env:TEMP\runtime.tar.gz" -Algorithm SHA256).Hash.ToLowerInvariant() -ne $env:ARCHIVE_SHA.ToLowerInvariant()) { throw 'Archive checksum mismatch' }
New-Item -ItemType Directory "$env:TEMP\runtime"
tar -xzf "$env:TEMP\runtime.tar.gz" -C "$env:TEMP\runtime"
if (-not (Test-Path "${env:ProgramFiles(x86)}\Inno Setup 6\ISCC.exe")) { choco install innosetup --yes --no-progress; if ($LASTEXITCODE) { throw "Inno Setup installation failed" } }
$runtime = "$env:TEMP\runtime\otelcol-contrib.exe"
& agent/packaging/build-windows.ps1 -Runtime $runtime -RuntimeSha256 (Get-FileHash $runtime -Algorithm SHA256).Hash
foreach ($file in @('agent/install-windows.ps1','agent/uninstall-windows.ps1','agent/packaging/build-windows.ps1')) {
  $tokens=$null; $errors=$null
  [System.Management.Automation.Language.Parser]::ParseFile((Resolve-Path $file),[ref]$tokens,[ref]$errors) | Out-Null
  if ($errors.Count) { throw "PowerShell parse failed: $file" }
}
& agent/packaging/stage/OpsControlService.exe --help
if (-not (Test-Path agent/packaging/output/OpsControlAgent-1.5.0-Windows-x64.exe)) { throw 'Compiled installer missing' }

python -m compileall -q agent
if ($LASTEXITCODE) { throw 'Agent Python compilation failed' }
foreach ($file in @('agent/install-windows.ps1','agent/uninstall-windows.ps1','agent/packaging/build-windows.ps1')) {
  $tokens=$null; $errors=$null
  [System.Management.Automation.Language.Parser]::ParseFile((Resolve-Path $file),[ref]$tokens,[ref]$errors) | Out-Null
  if ($errors.Count) { throw "PowerShell parse failed: $file" }
}
